   subroutine get_group(statistic,trend,beta,wght,nreg,model,minsize,info)
      integer,intent(in)::statistic,trend
      real(dp),intent(out)::beta(4,221),wght(221)
      integer,intent(out)::nreg,model,minsize,info
      info=0
      select case(10*statistic+trend)
      case(11)
      beta=beta_11
      wght=wght_11
      nreg=1
      model=2
      minsize=20
      case(12)
      beta=beta_12
      wght=wght_12
      nreg=2
      model=2
      minsize=20
      case(13)
      beta=beta_13
      wght=wght_13
      nreg=3
      model=3
      minsize=20
      case(14)
      beta=beta_14
      wght=wght_14
      nreg=4
      model=3
      minsize=20
      case(21)
      beta=beta_21
      wght=wght_21
      nreg=1
      model=2
      minsize=20
      case(22)
      beta=beta_22
      wght=wght_22
      nreg=2
      model=2
      minsize=20
      case(23)
      beta=beta_23
      wght=wght_23
      nreg=3
      model=3
      minsize=20
      case(24)
      beta=beta_24
      wght=wght_24
      nreg=4
      model=3
      minsize=20
      case default
      beta=0.0_dp
      wght=0.0_dp
      nreg=0
      model=0
      minsize=0
      info=-1
      end select
   end subroutine get_group
   pure real(dp) function eval_surface(b,model,nreg,nobs) result(v)
      real(dp),intent(in)::b(4)
      integer,intent(in)::model,nreg,nobs
      real(dp)::on
      if(nobs==0)then
      v=b(1)
      return
      end if
      select case(model)
      case(2)
      on=1.0_dp/real(nobs,dp)
      v=b(1)+b(2)*on+b(3)*on**2
      case(3)
      on=1.0_dp/real(nobs,dp)
      v=b(1)+b(2)*on+b(3)*on**2+b(4)*on**3
      case(4)
      on=1.0_dp/real(nobs-nreg,dp)
      v=b(1)+b(2)*on+b(3)*on**2
      case(5)
      on=1.0_dp/real(nobs-nreg,dp)
      v=b(1)+b(2)*on+b(3)*on**2+b(4)*on**3
      case default
      v=huge(1.0_dp)
      end select
   end function eval_surface

   subroutine gls_small(x,y,omega,nvar,b,cov,ssrt,info)
      real(dp),intent(in)::x(:,:),y(:),omega(:,:)
      integer,intent(in)::nvar
      real(dp),allocatable,intent(out)::b(:),cov(:,:)
      real(dp),intent(out)::ssrt
      integer,intent(out)::info
      real(dp),allocatable::oi(:,:),xtoi(:,:),rhs(:),res(:)
      call invert_spd(omega,oi,info)
      if(info/=0)call invert_matrix(omega,oi,info)
      if(info/=0)return
      xtoi=matmul(transpose(x(:,1:nvar)),oi)
      call invert_spd(matmul(xtoi,x(:,1:nvar)),cov,info)
      if(info/=0)call invert_matrix(matmul(xtoi,x(:,1:nvar)),cov,info)
      if(info/=0)return
      rhs=matmul(xtoi,y)
      b=matmul(cov,rhs)
      res=y-matmul(x(:,1:nvar),b)
      ssrt=dot_product(res,matmul(oi,res))
   end subroutine gls_small

   real(dp) function mackinnon_quantile(prob,nobs,trend,statistic,info) result(cval)
      real(dp),intent(in)::prob
      integer,intent(in)::nobs,trend,statistic
      integer,intent(out),optional::info
      integer::imin,i,j,ic,jc,nph,nptop,np,np1,nx,mo,nr,ms,ier
      real(dp)::bt(4,221),wt(221)
      real(dp)::diff,diffm,top,bot,ssrt,sd4,ttest,z
      real(dp),allocatable::crits(:),yv(:),xm(:,:),om(:,:),g(:),cov(:,:)
      call get_group(statistic,trend,bt,wt,nr,mo,ms,ier)
      np=9
      if(ier/=0)then
      cval=huge(1.0_dp)
      if(present(info))info=ier
      return
      end if
      if(statistic<1.or.statistic>2.or.trend<1.or.trend>4.or.prob<=0.0_dp.or.prob>=1.0_dp)then
      cval=huge(1.0_dp)
      ier=-1
      if(present(info))info=ier
      return
      end if
      if(nobs/=0.and.nobs<ms)ier=1
      allocate(crits(221))
      do i=1,221
      crits(i)=eval_surface(bt(:,i),mo,nr,nobs)
      end do
      diffm=huge(1.0_dp)
      imin=1
      do i=1,221
      diff=abs(prob-probs(i))
      if(diff<diffm)then
      diffm=diff
      imin=i
      end if
      end do
      nph=np/2
      nptop=221-nph
      if(imin>nph.and.imin<nptop)then
         np1=np
         allocate(yv(np1),xm(np1,4),om(np1,np1))
         do i=1,np1
         ic=imin-nph-1+i
         yv(i)=crits(ic)
         xm(i,:)=[1.0_dp,cnorm(ic),cnorm(ic)**2,cnorm(ic)**3]
         end do
         do i=1,np1
         ic=imin-nph-1+i
         do j=i,np1
         jc=imin-nph-1+j
         top=probs(ic)*(1-probs(jc))
         bot=probs(jc)*(1-probs(ic))
         om(i,j)=wt(ic)*wt(jc)*sqrt(top/bot)
         om(j,i)=om(i,j)
         end do
         end do
      else
         if(imin<np)then
         np1=max(5,imin+nph)
         allocate(yv(np1),xm(np1,4),om(np1,np1))
         do i=1,np1
         yv(i)=crits(i)
         xm(i,:)=[1.0_dp,cnorm(i),cnorm(i)**2,cnorm(i)**3]
         end do
            do i=1,np1
            do j=i,np1
            top=probs(i)*(1-probs(j))
            bot=probs(j)*(1-probs(i))
            om(i,j)=wt(i)*wt(j)*sqrt(top/bot)
            om(j,i)=om(i,j)
            end do
            end do
         else
         np1=max(5,222-imin+nph)
         allocate(yv(np1),xm(np1,4),om(np1,np1))
         om=0.0_dp
         do i=1,np1
         ic=222-i
         yv(i)=crits(ic)
         xm(i,:)=[1.0_dp,cnorm(ic),cnorm(ic)**2,cnorm(ic)**3]
         om(i,i)=1.0_dp
         end do
         end if
      end if
      call gls_small(xm,yv,om,4,g,cov,ssrt,ier)
      if(ier/=0)then
      cval=huge(1.0_dp)
      if(present(info))info=ier
      return
      end if
      sd4=sqrt(max(0.0_dp,(ssrt/real(np1-4,dp))*cov(4,4)))
      if(sd4>0.0_dp)then
         ttest=abs(g(4))/sd4
      else
         ttest=huge(1.0_dp)
      end if
      z=normal_quantile(prob)
      if(ttest>2.0_dp)then
      cval=g(1)+g(2)*z+g(3)*z*z+g(4)*z**3
      else
      call gls_small(xm,yv,om,3,g,cov,ssrt,ier)
      if(ier/=0)then
      cval=huge(1.0_dp)
      if(present(info))info=ier
      return
      end if
      cval=g(1)+g(2)*z+g(3)*z*z
      end if
      if(present(info))info=ier
   end function mackinnon_quantile

   real(dp) function mackinnon_pvalue(stat,nobs,trend,statistic,info) result(pval)
      real(dp),intent(in)::stat
      integer,intent(in)::nobs,trend,statistic
      integer,intent(out),optional::info
      integer::imin,i,j,ic,jc,nph,nptop,np,np1,mo,nr,ms,ier
      real(dp)::bt(4,221),wt(221)
      real(dp)::diff,diffm,top,bot,ssrt,sd4,ttest,crfit
      real(dp),allocatable::crits(:),yv(:),xm(:,:),om(:,:),g(:),cov(:,:)
      call get_group(statistic,trend,bt,wt,nr,mo,ms,ier)
      np=9
      if(ier/=0)then
      pval=-1.0_dp
      if(present(info))info=ier
      return
      end if
      if(statistic<1.or.statistic>2.or.trend<1.or.trend>4)then
      pval=-1.0_dp
      ier=-1
      if(present(info))info=ier
      return
      end if
      if(nobs/=0.and.nobs<ms)ier=1
      allocate(crits(221))
      do i=1,221
      crits(i)=eval_surface(bt(:,i),mo,nr,nobs)
      end do
      diffm=huge(1.0_dp)
      imin=1
      do i=1,221
      diff=abs(stat-crits(i))
      if(diff<diffm)then
      diffm=diff
      imin=i
      end if
      end do
      nph=np/2
      nptop=221-nph
      if(imin>nph.and.imin<nptop)then
         np1=np
         allocate(yv(np1),xm(np1,4),om(np1,np1))
         do i=1,np1
         ic=imin-nph-1+i
         yv(i)=cnorm(ic)
         xm(i,:)=[1.0_dp,crits(ic),crits(ic)**2,crits(ic)**3]
         end do
         do i=1,np1
         ic=imin-nph-1+i
         do j=i,np1
         jc=imin-nph-1+j
         top=probs(ic)*(1-probs(jc))
         bot=probs(jc)*(1-probs(ic))
         om(i,j)=wt(ic)*wt(jc)*sqrt(top/bot)
         om(j,i)=om(i,j)
         end do
         end do
      else
         if(imin<np)then
         np1=max(5,imin+nph)
         allocate(yv(np1),xm(np1,4),om(np1,np1))
         do i=1,np1
         yv(i)=cnorm(i)
         xm(i,:)=[1.0_dp,crits(i),crits(i)**2,crits(i)**3]
         end do
            do i=1,np1
            do j=i,np1
            top=probs(i)*(1-probs(j))
            bot=probs(j)*(1-probs(i))
            om(i,j)=wt(i)*wt(j)*sqrt(top/bot)
            om(j,i)=om(i,j)
            end do
            end do
         else
         np1=max(5,222-imin+nph)
         allocate(yv(np1),xm(np1,4),om(np1,np1))
         om=0.0_dp
         do i=1,np1
         ic=222-i
         yv(i)=cnorm(ic)
         xm(i,:)=[1.0_dp,crits(ic),crits(ic)**2,crits(ic)**3]
         om(i,i)=1.0_dp
         end do
         end if
      end if
      call gls_small(xm,yv,om,4,g,cov,ssrt,ier)
      if(ier/=0)then
      pval=-1.0_dp
      if(present(info))info=ier
      return
      end if
      sd4=sqrt(max(0.0_dp,(ssrt/real(np1-4,dp))*cov(4,4)))
      if(sd4>0.0_dp)then
         ttest=abs(g(4))/sd4
      else
         ttest=huge(1.0_dp)
      end if
      if(ttest>2.0_dp)then
      crfit=g(1)+g(2)*stat+g(3)*stat**2+g(4)*stat**3
      else
      call gls_small(xm,yv,om,3,g,cov,ssrt,ier)
      if(ier/=0)then
      pval=-1.0_dp
      if(present(info))info=ier
      return
      end if
      crfit=g(1)+g(2)*stat+g(3)*stat**2
      end if
      pval=normal_cdf(crfit)
      if(present(info))info=ier
   end function mackinnon_pvalue

   subroutine unitroot_table(trend,statistic,table,info)
      integer,intent(in)::trend,statistic
      real(dp),intent(out)::table(6,8)
      integer,intent(out),optional::info
      real(dp),parameter::p(8)=[0.01_dp,0.025_dp,0.05_dp,0.1_dp,0.9_dp,0.95_dp,0.975_dp,0.99_dp]
      integer,parameter::nn(6)=[25,50,100,250,500,0]
      integer::i,j,ier
      ier=0
      do i=1,6
      do j=1,8
      table(i,j)=mackinnon_quantile(p(j),nn(i),trend,statistic,ier)
      end do
      end do
      if(present(info))info=ier
   end subroutine unitroot_table
end module urca_mackinnon
